package com.railway.authservice.service;
import com.railway.authservice.entity.*;import com.railway.authservice.repository.*;import com.railway.authservice.dto.*;
import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.test.web.servlet.MockMvc;
import java.util.UUID;
import static org.junit.jupiter.api.Assertions.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest(properties={"spring.config.import=","spring.cloud.config.enabled=false","eureka.client.enabled=false","spring.cloud.compatibility-verifier.enabled=false","spring.datasource.url=jdbc:h2:mem:admin-users;MODE=MySQL","spring.datasource.driver-class-name=org.h2.Driver","spring.jpa.hibernate.ddl-auto=create-drop","spring.mail.host=localhost","jwt.secret=test-only-jwt-secret-with-at-least-32-bytes","jwt.expirationMs=900000","auth.bootstrap-admin.enabled=false"}) @AutoConfigureMockMvc
class AdminUserIntegrationTest {
 @Autowired AdminUserService service;@Autowired AuthService auth;@Autowired AuthUserRepository users;@Autowired PasswordEncoder passwords;@Autowired MockMvc mvc;
 private AuthUser create(AuthUser.Role role){String name=UUID.randomUUID().toString().replace("-","").substring(0,12);return users.save(AuthUser.builder().username(name).publicUsername("u"+name).email(name+"@example.test").password(passwords.encode("Password123!")).role(role).provider(AuthUser.Provider.LOCAL).isVerified(true).emailVerified(true).status(AuthUser.Status.ACTIVE).build());}
 private AuthResponse login(AuthUser u){var request=new LoginRequest();request.setIdentifier(u.getUsername());request.setPassword("Password123!");return auth.login(request);}
 @Test void blockingRevokesSessionsAndReactivationRequiresNewLogin()throws Exception{var a=create(AuthUser.Role.ADMIN);var p=create(AuthUser.Role.PASSENGER);var first=login(p);var second=login(p);service.status(a.getUsername(),p.getUsername(),"BLOCKED");assertThrows(RuntimeException.class,()->auth.refreshToken(first.getRefreshToken()));assertThrows(RuntimeException.class,()->auth.refreshToken(second.getRefreshToken()));assertThrows(RuntimeException.class,()->login(p));mvc.perform(post("/api/auth/logout").header("Authorization","Bearer "+first.getAccessToken())).andExpect(status().isUnauthorized());service.status(a.getUsername(),p.getUsername(),"ACTIVE");assertNotNull(login(p));assertThrows(RuntimeException.class,()->auth.refreshToken(first.getRefreshToken()));}
 @Test void selfAdminsAndDeletedAccountsCannotBeChanged(){var a=create(AuthUser.Role.ADMIN);var other=create(AuthUser.Role.ADMIN);var p=create(AuthUser.Role.PASSENGER);assertThrows(RuntimeException.class,()->service.status(a.getUsername(),a.getUsername(),"BLOCKED"));assertThrows(RuntimeException.class,()->service.status(a.getUsername(),other.getUsername(),"BLOCKED"));p.setStatus(AuthUser.Status.DELETED);users.save(p);assertThrows(RuntimeException.class,()->service.status(a.getUsername(),p.getUsername(),"ACTIVE"));assertThrows(RuntimeException.class,()->service.status(a.getUsername(),p.getUsername(),"ADMIN"));}
 @Test void searchesBothDisplayAndOwnershipNamesWithoutCredentialExposure()throws Exception{var a=create(AuthUser.Role.ADMIN);var p=create(AuthUser.Role.PASSENGER);var list=service.list(a.getUsername(),p.getPublicUsername(),"ACTIVE","PASSENGER",0,20,"id","desc");assertEquals(1,list.totalElements());assertEquals(p.getUsername(),list.content().getFirst().accountUsername());assertEquals(p.getPublicUsername(),list.content().getFirst().username());var token=login(a);mvc.perform(get("/api/auth/admin/users").param("search",p.getEmail()).header("Authorization","Bearer "+token.getAccessToken())).andExpect(status().isOk()).andExpect(jsonPath("$.content[0].password").doesNotExist()).andExpect(jsonPath("$.content[0].providerId").doesNotExist());}
 @Test void endpointsAndServiceRejectPassengers()throws Exception{var p=create(AuthUser.Role.PASSENGER);var token=login(p);for(String url:new String[]{"/api/auth/admin/users","/api/auth/admin/users/stats","/api/auth/admin/users/export"}){mvc.perform(get(url)).andExpect(status().isUnauthorized());mvc.perform(get(url).header("Authorization","Bearer "+token.getAccessToken())).andExpect(status().isForbidden());}mvc.perform(put("/api/auth/admin/users/other/status").header("Authorization","Bearer "+token.getAccessToken()).contentType("application/json").content("{\"status\":\"BLOCKED\"}")).andExpect(status().isForbidden());assertThrows(RuntimeException.class,()->service.list(p.getUsername(),"","","",0,20,"id","asc"));}
 @Test void filtersAndCsvProtectSpreadsheetConsumers(){var a=create(AuthUser.Role.ADMIN);var p=create(AuthUser.Role.PASSENGER);p.setEmail("=x@example.test");users.save(p);String csv=service.csv(a.getUsername(),p.getUsername(),"ACTIVE","PASSENGER");assertTrue(csv.contains("\"'=x@example.test\""));assertFalse(csv.contains("Password123!"));assertEquals(0,service.list(a.getUsername(),"%","","",0,20,"id","asc").totalElements());assertThrows(RuntimeException.class,()->service.list(a.getUsername(),"","","",0,101,"id","asc"));}
}
